template <int N>
struct Factorial {
  static constexpr int value = N * Factorial<N - 1>::value;
};

template <>
struct Factorial<0> {
  static constexpr int value = 1;
};

int main() {
  constexpr int result = Factorial<5>::value; // Calculated at compile time
  std::cout << result << std::endl; // Output: 120
  return 0;
}
