#include <iostream>
#include <type_traits>
template <typename T, typename U>
struct is_same_with_message {
    static const bool value = std::is_same<T, U>::value;
    static const char * message(){
        return value? "Types are the same": "Types are different";
    }
};
int main(){
    std::cout << is_same_with_message<int, int>::message() << std::endl; //Output: Types are the same
    std::cout << is_same_with_message<int, double>::message() << std::endl; //Output: Types are different
    return 0;
}
// Demonstrates compile-time type checking and message generation using template metaprogramming.
